def collect(index: list[dict], since: str, epics: list[dict]) -> dict:
    work, unmatched = defaultdict(lambda: {"prs": [], "epics": []}), []
    for pr in merged_prs(since):
        files = gh(f"repos/RhinoHealth/fcp/pulls/{pr['number']}/files", "--paginate", "--jq", ".[].filename")
        pages = [p["path"] for p in index
                 if any(g.startswith("fcp:") and fnmatch.filter(files, g[4:]) for g in p["applies_to"])]
        for path in pages:
            work[path]["prs"].append(pr)
        if not pages:
            unmatched.append(pr)
    for epic in epics:  # from read-only JQL: epics moved to Done since `since`
        pages = [p["path"] for p in index if epic["key"] in p["sources"]]
        for path in pages:
            work[path]["epics"].append(epic)
        if not pages:
            unmatched.append(epic)
    return {"pages": work, "unmatched": unmatched}
